import java.sql.*;
public class DbQ {public static void main(String[] a)throws Exception{try(Connection c=DriverManager.getConnection("jdbc:postgresql://localhost:5432/mindmark","postgres","123456"); Statement s=c.createStatement()){try(ResultSet r=s.executeQuery("select code,name from auth_role order by code")){System.out.println("roles");while(r.next())System.out.println(r.getString(1)+" "+r.getString(2));}try(ResultSet r=s.executeQuery("select user_id,role_code from auth_user_role where user_id='u-teacher-001' order by role_code")){System.out.println("teacher roles");while(r.next())System.out.println(r.getString(1)+" "+r.getString(2));}}}}
